using namespace std;
void dlr(string z, string h){
	if(z.empty() || h.empty()) return;  
	char now_root = *(h.end() - 1);  
	cout << now_root;
	int zroot_index = z.find(now_root);  
    dlr(z.substr(0, zroot_index), h.substr(0, zroot_index));  
    dlr(z.substr(zroot_index + 1), h.substr(zroot_index, h.size() - zroot_index - 1));  
}
